{"query":"query simulateTransactions($chainId: Int!, $transactions: [Transaction!]!, $domain: String) {
  simulateTransactions(
    chainID: $chainId
    transactions: $transactions
    domain: $domain
  ) {
    scanning {
      result
      description
    }
    error {
      message
      type
    }
    gas {
      estimate
    }
    simulation {
      in {
        ...change
      }
      out {
        ...change
      }
      approvals {
        asset {
          ...asset
        }
        spender {
          ...target
        }
        quantityAllowed
        quantityAtRisk
        expiration
      }
      meta {
        transferTo {
          ...target
        }
        to {
          ...target
        }
      }
      delegation {
        address
        name
        iconURL
        created
        sourceCodeStatus
      }
    }
  }
}

fragment change on TransactionSimulationChange {
  asset {
    ...asset
  }
  quantity
}

fragment asset on TransactionSimulationAsset {
  assetCode
  decimals
  iconURL
  name
  network
  symbol
  type
  interface
  tokenId
  status
}

fragment target on TransactionSimulationTarget {
  address
  name
  iconURL
  function
  created
  sourceCodeStatus
}","variables":{"chainId":1,"transactions":[{"from":"0x41C36c21b31C67e1c645CeE831dd5E4BfBF0cbC9","to":"0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48","value":"0","data":"0x095ea7b300000000000000000000000087870bca3f3fd6335c3f4ce8392d69350b4fa4e200000000000000000000000000000000000000000000000000000000000f4240"}],"domain":"https://beta.walletbeat.eth.limo/"},"operationName":"simulateTransactions"}

